mapper.select:
SELECT t.TRADE_ID tradeId,/**交易编号**/ t.F_TRADE_ID outTradeId, /*外部成交编号*/ deal1.BOOKSET_ID prodId,/**金融产品代码**/ bok.BOOKSET_NAME prodName,/**金融产品名称**/ zc.FINPROD_ID assetId, /**资产代码**/ zc.FINPROD_ABBR assetAbbr,/**资产简称**/ t.PS ps,/**交易方向**/ t.TRADE_DATE tradeDate,/**交易日**/ t.SETTLE_DATE settleDate, CASE WHEN t.PS in(#{PS_T01},#{PS_T02}) THEN t.PRIN_AMT WHEN t.PS in(#{PS_T05}) then t.FPRICE_AMT WHEN t.PS in(#{PS_T19}) then t.SHARE_AMT*t.UNIT_CPRICE ELSE t.TRADE_AMT END AS tradeAmt,/**成交金额**/ t.SHARE_AMT dealNum,/**交易份额**/ t.CCY ccy,/**币种**/ t.TRADE_AMT settleAmt,/**结算金额**/ t.MY_ACCT_NO trdMyAcctNo,/**资金账户**/ d.GEN_TYPE dataSource /**数据来源**/ FROM TRD_PRODUCT_DEAL t LEFT JOIN TRD_PRODUCT_DEAL_ADD d on t.TRADE_ID = d.TRADE_ID LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN BOK_DEAL_ACCOUNTING deal1 on deal1.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_BOOKSET bok on bok.BOOKSET_ID = deal1.BOOKSET_ID where t.BUSI_TYPE IN(#{busiType_06},#{busiType_07}) and t.FINPROD_TYPE = #{finprodType}
and t.TRADE_ID like concat(concat('%',#{tradeId}),'%')
and deal1.BOOKSET_ID IN
#{finprodId}
and zc.FINPROD_ID IN
#{assetId}
and t.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and t.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND t.PS IN
#{ps}
AND d.GEN_TYPE IN
#{dataSource}
order by t.TRADE_ID desc

SELECT t.TRADE_ID tradeId,/**交易编号**/ t.F_TRADE_ID outTradeId, /*外部成交编号*/ deal1.BOOKSET_ID prodId,/**金融产品代码**/ bok.BOOKSET_NAME prodName,/**金融产品名称**/ zc.FINPROD_ID assetId, /**资产代码**/ zc.FINPROD_ABBR assetAbbr,/**资产简称**/ t.PS ps,/**交易方向**/ t.CCY ccy,/**币种**/
t.TRADE_DATE tradeDate,/**交易日期**/ t.SETTLE_DATE settleDate,/**结算日期**/ t.PRIN_AMT tradeAmt,/**成交金额**/ t.SHARE_AMT dealNum,/**成交数量**/ t.MY_ACCT_NO trdMyAcctNo/**资金账户**/
/*认购*/ t.TRADE_DATE applyDate,/**申请日期**/ t.SETTLE_DATE subSettleDate,/**结算日期**/ t.TRADE_AMT applyAmt,/**申请金额**/ t.MY_ACCT_NO subMyAcctNo/**资金账户**/
/*申购*/ t.TRADE_DATE purApplyDate,/**申请日期**/ t.SETTLE_DATE purSettleDate,/**结算日期**/ t.TRADE_AMT purApplyAmt,/**申请金额**/ t.MY_ACCT_NO purMyAcctNo/**资金账户**/
/*认购确认*/ t.TRADE_DATE subConfirmDate,/**确认日期**/ t.TRADE_AMT subConfirmAmt,/**确认金额**/ t.SHARE_AMT subConfirmNum,/**确认数量**/ t.INT_AMT raiseInterest,/**募集期利息**/ t.FEE_AMT_UNPAY subFee,/**认购费**/ t.MY_ACCT_NO subConfirmMyAcctNo/**资金账户**/
/*申购确认*/ t.TRADE_DATE purConfirmDate,/**确认日期**/ t.FPRICE_AMT purConfirmAmt,/**确认金额**/ t.SHARE_AMT purConfirmNum,/**确认数量**/ t.UNIT_CPRICE purUnitValue,/**单位净值**/ t.INT_AMT interestIncome,/**利息收入**/ t.FEE_AMT_PAY purFee,/**申购费**/ t.MY_ACCT_NO purConfirmMyAcctNo/**资金账户**/
t.TRADE_DATE redConfirmDate,/**确认日期**/ t.SHARE_AMT*t.UNIT_CPRICE redConfirmAmt,/**确认金额**/ t.SHARE_AMT redConfirmNum,/**确认数量**/ t.UNIT_CPRICE redUnitValue,/**单位净值**/ t.FEE_AMT_PAY redFee,/**赎回费**/ null arriveDate,/**到账日期**/ t.MY_ACCT_NO redMyAcctNo/**资金账户**/
FROM TRD_PRODUCT_DEAL t LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN BOK_DEAL_ACCOUNTING deal1 on deal1.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_BOOKSET bok on bok.BOOKSET_ID = deal1.BOOKSET_ID where t.TRADE_ID = #{tradeId,jdbcType=VARCHAR} and t.BUSI_TYPE IN(#{busiType_06},#{busiType_07}) and rownum=1

mapper.delete:
